/// <summary>
/// A COC extension class of GUPVendPriceAdmTrans table in Metcash
/// </summary>
[ExtensionOf(tableStr(GUPVendPriceAdmTrans))]
final class MET_GUPVendPriceAdmTrans_Extension
{
}

Method.Source:
/// <summary>
/// Initalises from account code.
/// </summary>
public void initFromAccountCode()
{
    CurrencyCode currency = this.Currency;

    next initFromAccountCode();

    //Bug 320675 : CB129 - Price Changes - Supplier List Price - Currency value incorrectly updated on old record when the Currency value is different for the new record - start
    if (currency)
    {
        this.Currency = currency;
    }
    //Bug 320675 : CB129 - Price Changes - Supplier List Price - Currency value incorrectly updated on old record when the Currency value is different for the new record - end

}

/// <summary>
/// initFromGUPVendPriceAdmTrans used in copyline and pack change functionality
/// Bug 242610: CB267 - Claim From Vendor flag not copied from Temporary Item For Pack Change to the Original item when a Pack Change is processed
/// </summary>
/// <param name = "_gupVendPriceAdmTrans">GUPVendPriceAdmTrans</param>
public void initFromGUPVendPriceAdmTrans(GUPVendPriceAdmTrans _gupVendPriceAdmTrans)
{
    next initFromGUPVendPriceAdmTrans(_gupVendPriceAdmTrans);
    this.METVendClaimEnabled = _gupVendPriceAdmTrans.METVendClaimEnabled;
}

/// <summary>
/// COC for checkDatesOverlap method
///Bug 302090: CB129 - Pack Changes - Immediate Pack Change not processed correctly in D365 (Issue 3 - Supplier list price)
/// </summary>
public boolean checkDatesOverlap()
{
    boolean ret;
    GUPVendPriceAdmTrans vendPriceAdmTransOverlap;

    ret = next checkDatesOverlap();
    if (!ret)
    {
        switch (this.AccountCode)
        {
            case TableGroupAll::Table :
                select FromDate, ToDate, LineNum, JournalNum from vendPriceAdmTransOverlap
                where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                    && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                    && (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::All
                    || (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::Table
                        && vendPriceAdmTransOverlap.AccountRelation == this.AccountRelation))
                    && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                        || (this.ToDate
                            && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                            && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                        || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                    && vendPriceAdmTransOverlap.RecId != this.RecId
                    && vendPriceAdmTransOverlap.unitId == this.UnitId ;

                if (!vendPriceAdmTransOverlap)
                {
                    VendTable vendTable;
                    GUPVendPriceGroupLink priceGroupLink;

                    select FromDate, ToDate, LineNum, JournalNum from vendPriceAdmTransOverlap
                    where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                        && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                        && vendPriceAdmTransOverlap.AccountCode == TableGroupAll::GroupId
                        && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                            || (this.ToDate
                                && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                                && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                            || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                        && vendPriceAdmTransOverlap.RecId != this.RecId
                        && vendPriceAdmTransOverlap.unitId == this.UnitId
                join priceGroupLink
                    where priceGroupLink.VendPriceGroupId == vendPriceAdmTransOverlap.AccountRelation
                exists join vendTable
                    where vendTable.RecId == priceGroupLink.VendRecId
                        && vendTable.AccountNum == this.AccountRelation;
                }
                break;
            case TableGroupAll::GroupId :
                select FromDate, ToDate, LineNum, JournalNum from vendPriceAdmTransOverlap
                where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                    && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                    && (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::All
                    || (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::GroupId
                        && vendPriceAdmTransOverlap.AccountRelation == this.AccountRelation))
                    && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                        || (this.ToDate
                            && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                            && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                        || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                    && vendPriceAdmTransOverlap.RecId != this.RecId
                    && vendPriceAdmTransOverlap.unitId == this.UnitId;

                if (!vendPriceAdmTransOverlap)
                {
                    VendTable vendTable;
                    GUPVendPriceGroupLink priceGroupLink;

                    select FromDate, ToDate, LineNum, JournalNum from vendPriceAdmTransOverlap
                    where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                        && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                        && vendPriceAdmTransOverlap.AccountCode == TableGroupAll::Table
                        && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                            || (this.ToDate
                                && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                                && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                            || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                        && vendPriceAdmTransOverlap.RecId != this.RecId
                        && vendPriceAdmTransOverlap.unitId == this.UnitId
                join RecId from vendTable
                    where vendTable.AccountNum == vendPriceAdmTransOverlap.AccountRelation
                exists join priceGroupLink
                    where priceGroupLink.VendRecId == vendTable.RecId
                        && priceGroupLink.VendPriceGroupId == this.AccountRelation;
                }
                break;
            case TableGroupAll::All :
                select FromDate, ToDate, LineNum, JournalNum from vendPriceAdmTransOverlap
                where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                    && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                    && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                        || (this.ToDate
                            && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                            && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                        || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                    && vendPriceAdmTransOverlap.RecId != this.RecId
                    && vendPriceAdmTransOverlap.unitId == this.UnitId;
                break;
        }

        if (!vendPriceAdmTransOverlap)
        {
            infolog.clear();
            ret = true;
            return ret;
        }
    }
    return ret;
}
